     1	//! Case folding and normalization.
     2	
     3	/// Mirrors `idna::to_lower()`, which is
     4	/// `std::transform(s.begin(), s.end(), out.begin(), ::tolower)`.
     5	///
     6	/// `::tolower` runs in the default "C" locale, so only `A`..=`Z` shift by 32;
     7	/// every other byte — including the continuation bytes of a multi-byte UTF-8
     8	/// sequence — is returned unchanged. Folding byte-wise is therefore both
     9	/// faithful and safe: it never rewrites a non-ASCII code point.
    10	pub fn to_lower(input: &[u8]) -> Vec<u8> {
    11	    input.iter().map(|&b| b.to_ascii_lowercase()).collect()
    12	}
    13	
    14	/// Mirrors `idna::normalize()`, which forwards straight to `to_lower()`.
    15	pub fn normalize(input: &[u8]) -> Vec<u8> {
    16	    to_lower(input)
    17	}
