     1	//! Domain and label predicates.
     2	
     3	use super::{MAX_DOMAIN_LENGTH, MAX_LABEL_LENGTH};
     4	
     5	/// Mirrors `idna::is_valid_domain()`: `!s.empty() && s.length() <= 255`.
     6	///
     7	/// The bound is a byte count, so a 86-code-point CJK domain (258 bytes) is
     8	/// rejected even though it is well under 255 characters.
     9	pub fn is_valid_domain(input: &[u8]) -> bool {
    10	    !input.is_empty() && input.len() <= MAX_DOMAIN_LENGTH
    11	}
    12	
    13	/// Mirrors `idna::is_valid_label()`: `!s.empty() && s.length() <= 63`.
    14	///
    15	/// Note the C++ routine checks the whole string, not each dot-separated label,
    16	/// and applies no character rules at all.
    17	pub fn is_valid_label(input: &[u8]) -> bool {
    18	    !input.is_empty() && input.len() <= MAX_LABEL_LENGTH
    19	}
    20	
    21	/// Mirrors `idna::is_ascii_domain()`: every byte must be non-negative when read
    22	/// as a `char`, i.e. `< 0x80`. An empty string is vacuously ASCII.
    23	pub fn is_ascii_domain(input: &[u8]) -> bool {
    24	    input.iter().all(|&b| b < 0x80)
    25	}
    26	
    27	/// Mirrors `idna::is_idn_domain()`: `!is_ascii_domain(s)`.
    28	pub fn is_idn_domain(input: &[u8]) -> bool {
    29	    !is_ascii_domain(input)
    30	}

