#!/usr/bin/perl
# Differential fuzzer, round 1, strategy "ace-prefix".
#
# Every mutation is built around the "xn--" ACE prefix: exact, upper/mixed
# case, truncated, repeated, embedded mid-string, per-label, prefix-only,
# prefix + one char, and prefix with trailing dots.
#
# Each input is passed as a SINGLE argv element (raw bytes) to both binaries
# via fork + exec LIST (never through a shell, never re-split).  stdout goes to
# separate files compared with `cmp -s`; exit codes are compared too.

use strict;
use warnings;
use POSIX ":sys_wait_h";

my $CPP  = "/workspace/dataset/test11_executable";
my $RUST = "/output/test11";
my $DIR  = "/tmp/wf-fuzz-r1-3/run";
mkdir $DIR;

my $C_OUT = "$DIR/c.out";
my $R_OUT = "$DIR/r.out";
my $C_ERR = "$DIR/c.err";
my $R_ERR = "$DIR/r.err";

# ------------------------------------------------------------------ helpers

sub bash_lit {                     # exact bash $'..' literal, hex-escaped
    my ($s) = @_;
    return "\$'" . join('', map { sprintf('\\x%02x', ord $_) } split //, $s) . "'";
}

sub repro {
    my (@args) = @_;
    my $q = join(' ', map { bash_lit($_) } @args);
    return "$CPP $q    # vs:    $RUST $q";
}

sub pretty {                       # printable repr of a byte string
    my ($s) = @_;
    my $o = '';
    for my $c (split //, $s) {
        my $n = ord $c;
        if ($n >= 0x20 && $n < 0x7f && $c ne '\\') { $o .= $c }
        else { $o .= sprintf('\\x%02x', $n) }
    }
    return '"' . $o . '"';
}

sub slurp {
    my ($f) = @_;
    open(my $fh, '<:raw', $f) or return '';
    local $/;
    my $d = <$fh>;
    close $fh;
    return defined($d) ? $d : '';
}

# fork + exec LIST, stdout -> $out, stderr -> $err.  Returns wait status.
sub run_bin {
    my ($bin, $out, $err, @args) = @_;
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>:raw', $out) or exit 126;
        open(STDERR, '>:raw', $err) or exit 126;
        exec { $bin } ($bin, @args);
        exit 127;
    }
    waitpid($pid, 0);
    return $?;
}

sub status_str {
    my ($st) = @_;
    my $sig = $st & 127;
    return $sig ? "signal $sig" : "exit " . ($st >> 8);
}

# Runs both, returns (same_stdout, cpp_status, rust_status)
sub compare {
    my (@args) = @_;
    unlink $C_OUT, $R_OUT, $C_ERR, $R_ERR;
    my $cs = run_bin($CPP,  $C_OUT, $C_ERR, @args);
    my $rs = run_bin($RUST, $R_OUT, $R_ERR, @args);
    my $same = (system('cmp', '-s', $C_OUT, $R_OUT) == 0) ? 1 : 0;
    my $esame = (system('cmp', '-s', $C_ERR, $R_ERR) == 0) ? 1 : 0;
    return ($same, $cs, $rs, $esame);
}

# --------------------------------------------------------------- generation

sub prefix_variants {
    my @out;
    # all case permutations of the two letters x dash counts 0..5
    for my $x ('x', 'X') {
        for my $n ('n', 'N') {
            for my $d (0 .. 5) { push @out, $x . $n . ('-' x $d) }
        }
    }
    push @out, ('', 'x', 'X', 'n', 'N', '-', '--', '---', '----');
    push @out, ('x-n--', '-xn--', 'x-n-', 'xn.-', 'xn_-', 'xn -', 'x n--',
                'xnn--', 'xxn--', 'xn--x', 'xn--n', 'xn---x', 'nx--', '-n--',
                'x--', 'xn+-', 'xn=-', 'XN-x', 'Xn-X', 'xN-n');
    push @out, ("xn\xe2\x80\x93\xe2\x80\x93",              # en dashes
                "\xef\xbd\x98\xef\xbd\x8e--",              # fullwidth xn
                "\x78\x6e\x2d\x2d", "\x78\x6e\x2d",
                "\xf8n--", "x\xee--", "\x78\x4e\x2d\x2d",
                "xn\x2d\xad", "xn--\xff", "\xffxn--");
    my (%seen, @uniq);
    for my $p (@out) { next if $seen{$p}++; push @uniq, $p }
    return @uniq;
}

my @BODIES = (
    '', 'a', 'ab', 'A', 'AB', 'Z', '0', '-', '.', '..', '...',
    'a.b', 'a..b', '.a', 'a.',
    'example.com', 'EXAMPLE.COM', 'ExAmPlE.CoM',
    'xn--a', 'xn--', 'XN--a',
    "\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e",       # 日本語
    "\xe4\xb8\xad\xe5\x9b\xbd.cn",                # 中国.cn
    "\xff", "\xff\xfe", "\x80", "\x7f", "\xc3",
    "\xed\xa0\x80", "\xf4\x90\x80\x80",
    "\n", "\r\n", "\t", ' ', '  a  ',
    '"', "'", "\\", "a\nb", 'a b', "a\tb",
    ('a' x 59), ('a' x 60), ('a' x 63), ('a' x 64),
    ('a' x 251), ('a' x 252), ('A' x 255), ('a' x 256),
);

# Each case is [tag, [argv...]]
sub gen_cases {
    my @cases;
    my @P = prefix_variants();

    # 1. prefix alone
    push @cases, ['prefix-only', [$_]] for @P;

    # 2. prefix + body
    for my $p (@P) { for my $b (@BODIES) { push @cases, ['prefix+body', [$p . $b]] } }

    # 3. prefix + exactly one char
    my @ONE = map { chr $_ } (0x01, 0x09, 0x0a, 0x0d, 0x20, 0x21, 0x2d, 0x2e,
                              0x2f, 0x30, 0x3a, 0x41, 0x5a, 0x5f, 0x61, 0x7a,
                              0x7e, 0x7f, 0x80, 0xc0, 0xed, 0xfe, 0xff);
    for my $p (@P) { for my $c (@ONE) { push @cases, ['prefix+1char', [$p . $c]] } }

    # 4. repeated prefixes 1..8
    for my $f ('xn--', 'XN--', 'Xn--', 'xN--', 'xn-', 'xn', 'x') {
        for my $n (1 .. 8) {
            my $base = $f x $n;
            push @cases, ['repeat', [$base]];
            push @cases, ['repeat', [$base . 'a']];
            push @cases, ['repeat', [$base . 'example.com']];
            push @cases, ['repeat', [$base . "\xe6\x97\xa5"]];
            push @cases, ['repeat', ['a' . $base]];
            push @cases, ['repeat', [$base . '.']];
            push @cases, ['repeat', ['.' . $base . '.']];
        }
    }

    # 5. embedded mid-string at every offset of small carriers
    for my $p ('xn--', 'XN--', 'xn-', 'xn', 'Xn--', 'xN--') {
        for my $carrier ('abcdef', 'a.b.c', '....', 'AB.CD', "\xff\xff\xff") {
            for my $i (0 .. length($carrier)) {
                push @cases, ['embedded',
                    [substr($carrier, 0, $i) . $p . substr($carrier, $i)]];
            }
        }
    }

    # 6. per-label placement
    for my $p ('xn--', 'XN--', 'Xn--', 'xN--', 'xn-', 'xn', 'x', '') {
        push @cases, ['per-label', ["a.$p"]];
        push @cases, ['per-label', ["a.${p}b"]];
        push @cases, ['per-label', ["${p}a.b"]];
        push @cases, ['per-label', ["a.b.${p}c"]];
        push @cases, ['per-label', ["$p.$p"]];
        push @cases, ['per-label', ["a.$p.b"]];
        push @cases, ['per-label', ["${p}a.${p}b"]];
        push @cases, ['per-label', ["a.b.c.$p"]];
        push @cases, ['per-label', ["$p.a.$p.b.$p"]];
        push @cases, ['per-label', ["${p}\xe6\x97\xa5.$p"]];
    }

    # 7. prefix with trailing / leading dots
    for my $p ('xn--', 'XN--', 'Xn--', 'xN--', 'xn-', 'xn', 'x', 'xn---',
               'xn--xn--') {
        for my $nd (0 .. 8) {
            my $d = '.' x $nd;
            push @cases, ['trailing-dots', [$p . $d]];
            push @cases, ['trailing-dots', [$d . $p]];
            push @cases, ['trailing-dots', [$d . $p . $d]];
            push @cases, ['trailing-dots', [$p . $d . 'a']];
            push @cases, ['trailing-dots', [$p . 'a' . $d]];
        }
    }

    # 8. length boundaries, prefix eating part of the budget
    for my $p ('xn--', 'XN--', 'xn-', 'xn', '') {
        for my $total (0, 1, 2, 3, 4, 5, 62, 63, 64, 65, 66, 67,
                       253, 254, 255, 256, 257, 258, 259) {
            my $pad = $total - length($p);
            next if $pad < 0;
            push @cases, ['length', [$p . ('a' x $pad)]];
            push @cases, ['length',
                [$p . ("\xe6\x97\xa5" x int($pad / 3)) . ('a' x ($pad % 3))]];
        }
    }

    # 9. prefix glued to exotic / invalid byte sequences
    my @EX = ("\xe2\x80\x8b", "\xef\xbb\xbf", "\xcc\x81", "\xc2\xad",
              "\xe3\x80\x82", "\xef\xbc\x8e", "\xf0\x9f\x92\xa9",
              "\xc0\x80", "\xf7\xbf\xbf\xbf", "\xfe\xff");
    for my $p ('xn--', 'XN--', 'xn-', 'xn') {
        for my $e (@EX) {
            push @cases, ['exotic', [$p . $e]];
            push @cases, ['exotic', [$e . $p]];
            push @cases, ['exotic', [$p . $e . $p]];
            push @cases, ['exotic', [$p . $e . 'a']];
        }
    }

    # 10. every single byte 1..255 around a prefix
    for my $c (1 .. 255) {
        my $b = chr $c;
        push @cases, ['bytesweep', ['xn--' . $b]];
        push @cases, ['bytesweep', [$b . 'xn--']];
        push @cases, ['bytesweep', ['xn-' . $b . 'a']];
        push @cases, ['bytesweep', ['x' . $b . 'n--a']];
        push @cases, ['bytesweep', ['xn' . $b . '--a']];
    }

    # 11. multi-argv (several xn-- flavours at once -> multi-line output)
    push @cases, ['multi-argv', ['xn--a', 'XN--a']];
    push @cases, ['multi-argv', ['xn--', 'xn--', 'xn--']];
    push @cases, ['multi-argv', ["xn--\xff", "\xffxn--", 'xn--.']];
    push @cases, ['multi-argv', ['', 'xn--', '']];
    push @cases, ['multi-argv', ['xn--' x 3, 'a.xn--b', 'xn--...']];
    push @cases, ['multi-argv', [('xn--a') x 12]];
    push @cases, ['multi-argv', ['xn--' . ('a' x 255), 'xn--']];

    # 12. no-argument default path
    push @cases, ['no-args', []];

    return @cases;
}

# ---------------------------------------------------------------- execution

my @cases   = gen_cases();
my $executed = 0;
my $skipped  = 0;
my $mismatch = 0;
my $errdiff  = 0;

for my $case (@cases) {
    my ($tag, $args) = @$case;
    if (grep { index($_, "\0") >= 0 } @$args) { $skipped++; next }

    my ($same, $cs, $rs, $esame) = compare(@$args);
    $executed++;

    if (!$same || $cs != $rs) {
        # must reproduce twice to count
        my $c1 = slurp($C_OUT); my $r1 = slurp($R_OUT);
        my ($same2, $cs2, $rs2) = compare(@$args);
        my $c2 = slurp($C_OUT); my $r2 = slurp($R_OUT);
        my $stable = ($same2 == $same && $cs2 == $cs && $rs2 == $rs
                      && $c1 eq $c2 && $r1 eq $r2) ? 'YES' : 'NO';
        $mismatch++;
        print "=" x 72, "\n";
        print "MISMATCH [$tag]  reproduced_twice=$stable\n";
        print "  argv    : ", join(', ', map { pretty($_) } @$args), "\n";
        print "  repro   : ", repro(@$args), "\n";
        print "  cpp  ", status_str($cs), "  stdout=", pretty($c1), "\n";
        print "  rust ", status_str($rs), "  stdout=", pretty($r1), "\n";
        $| = 1;
    }
    if (!$esame) {
        $errdiff++;
        print "STDERR-DIFF [$tag] ", repro(@$args), "\n" if $errdiff <= 10;
    }
}

print "=" x 72, "\n";
print "cases executed : $executed\n";
print "cases skipped  : $skipped\n";
print "mismatches     : $mismatch\n";
print "stderr diffs   : $errdiff\n";

