#!/usr/bin/perl
# Round 2 of the "ace-prefix" strategy: deeper / larger / exhaustive cases that
# round 1 sampled only lightly.
#   - huge inputs (1 KB .. 2 MB) with the prefix, exercising output size
#   - exhaustive: every byte 1..255 as the *whole* body after each prefix case
#   - one argv holding all 255 non-NUL bytes, prefixed / suffixed
#   - very deep prefix repetition (up to 4096 copies)
#   - upper-case prefixes glued to high bytes (::tolower on negative char)
#   - prefix straddling the 63/255 length thresholds byte-exactly
#   - many argv elements at once
use strict;
use warnings;

my $CPP  = "/workspace/dataset/test11_executable";
my $RUST = "/output/test11";
my $DIR  = "/tmp/wf-fuzz-r1-3/run2";
mkdir $DIR;
my ($C_OUT, $R_OUT, $C_ERR, $R_ERR) = ("$DIR/c.out", "$DIR/r.out", "$DIR/c.err", "$DIR/r.err");

sub bash_lit { my ($s)=@_; return "\$'".join('', map { sprintf('\\x%02x', ord $_) } split //, $s)."'" }
sub repro { my @a=@_; my $q=join(' ', map { bash_lit($_) } @a); return "$CPP $q    # vs:    $RUST $q" }
sub pretty {
    my ($s)=@_;
    my $t = length($s) > 220 ? substr($s,0,110)."...[".length($s)." bytes total]...".substr($s,-60) : $s;
    my $o='';
    for my $c (split //,$t){ my $n=ord $c; $o .= ($n>=0x20&&$n<0x7f&&$c ne '\\') ? $c : sprintf('\\x%02x',$n) }
    return '"'.$o.'"';
}
sub run_bin {
    my ($bin,$out,$err,@a)=@_;
    my $p=fork(); die "fork: $!" unless defined $p;
    if($p==0){ open(STDOUT,'>:raw',$out) or exit 126; open(STDERR,'>:raw',$err) or exit 126;
               exec {$bin} ($bin,@a); exit 127 }
    waitpid($p,0); return $?;
}
sub status_str { my ($s)=@_; my $g=$s&127; return $g ? "signal $g" : "exit ".($s>>8) }
sub compare {
    my @a=@_;
    unlink $C_OUT,$R_OUT,$C_ERR,$R_ERR;
    my $cs=run_bin($CPP,$C_OUT,$C_ERR,@a);
    my $rs=run_bin($RUST,$R_OUT,$R_ERR,@a);
    my $same=(system('cmp','-s',$C_OUT,$R_OUT)==0)?1:0;
    my $es=(system('cmp','-s',$C_ERR,$R_ERR)==0)?1:0;
    return ($same,$cs,$rs,$es);
}
sub sz { my ($f)=@_; my @s=stat($f); return defined $s[7] ? $s[7] : -1 }

my @cases;

# --- huge inputs -------------------------------------------------------
for my $n (1024, 4096, 16384, 65535, 65536, 131072, 1000000) {
    for my $p ('xn--','XN--','xn-','xn','') {
        push @cases, ['huge', [$p . ('a' x $n)]];
    }
    push @cases, ['huge', ['xn--' . ('A' x $n)]];
    push @cases, ['huge', ['xn--' . ("\xff" x $n)]];
    push @cases, ['huge', ['xn--' . ("\xe6\x97\xa5" x int($n/3))]];
    push @cases, ['huge', ['xn--' . ('.' x $n)]];
    push @cases, ['huge', ['xn--' . ('a.' x int($n/2))]];
}

# --- exhaustive single-byte bodies after every prefix flavour ----------
my @PF = ('xn--','XN--','Xn--','xN--','xn-','XN-','xn','XN','x','X','', 'xn---','xn--xn--');
for my $p (@PF) {
    for my $c (1 .. 255) { push @cases, ['exhaustive-byte', [$p . chr($c)]] }
}

# --- one argv containing every non-NUL byte ---------------------------
my $ALL = join('', map { chr $_ } (1 .. 255));
my $ALLREV = join('', map { chr $_ } reverse(1 .. 255));
for my $p ('xn--','XN--','xn-','xn','') {
    push @cases, ['all-bytes', [$p . $ALL]];
    push @cases, ['all-bytes', [$ALL . $p]];
    push @cases, ['all-bytes', [$p . $ALLREV . $p]];
    push @cases, ['all-bytes', [$p . $ALL x 3]];
}

# --- deep prefix repetition ------------------------------------------
for my $n (16, 32, 64, 100, 255, 256, 512, 1000, 4096) {
    for my $f ('xn--','XN--','xn-','xn','x') {
        push @cases, ['deep-repeat', [$f x $n]];
        push @cases, ['deep-repeat', [($f x $n) . 'a']];
    }
}

# --- upper prefix + high bytes (::tolower on negative char) -----------
for my $hi (0x80,0x81,0x9f,0xa0,0xbf,0xc0,0xdf,0xe0,0xef,0xf0,0xf7,0xf8,0xfe,0xff,
            0xc4,0xd0,0xd8,0xde,0xe4,0xf4) {
    for my $p ('XN--','Xn--','xN--','xn--','XN-','XN') {
        push @cases, ['tolower-high', [$p . chr($hi)]];
        push @cases, ['tolower-high', [$p . chr($hi) . 'AB']];
        push @cases, ['tolower-high', [chr($hi) . $p . chr($hi)]];
        push @cases, ['tolower-high', [$p . (chr($hi) x 8) . 'XN--']];
    }
}

# --- exact length thresholds around 63 / 255 with the prefix ----------
for my $p ('xn--','XN--','xn-','xn','x','') {
    for my $total (58 .. 68, 250 .. 260) {
        my $pad = $total - length($p);
        next if $pad < 0;
        push @cases, ['threshold', [$p . ('a' x $pad)]];
        push @cases, ['threshold', [$p . ('a' x ($pad-1)) . '.'] ] if $pad >= 1;
        push @cases, ['threshold', [$p . ('.' x $pad)]];
    }
}

# --- many argv elements ----------------------------------------------
for my $n (1, 2, 8, 64, 256, 1024) {
    push @cases, ['many-argv', [ map { 'xn--' . $_ } (1 .. $n) ]];
    push @cases, ['many-argv', [ ('xn--') x $n ]];
    push @cases, ['many-argv', [ map { ($_ % 2) ? 'XN--a' : "xn--\xff" } (1 .. $n) ]];
}

# --- prefix + trailing dots, longer runs -----------------------------
for my $p ('xn--','XN--','xn-','xn','x') {
    for my $nd (9 .. 40) {
        push @cases, ['long-dots', [$p . ('.' x $nd)]];
        push @cases, ['long-dots', [('.' x $nd) . $p . ('.' x $nd)]];
    }
}

my ($executed,$mismatch,$errdiff,$skipped) = (0,0,0,0);
$| = 1;
for my $c (@cases) {
    my ($tag,$args) = @$c;
    if (grep { index($_,"\0") >= 0 } @$args) { $skipped++; next }
    my ($same,$cs,$rs,$es) = compare(@$args);
    $executed++;
    if (!$same || $cs != $rs) {
        my $csz = sz($C_OUT); my $rsz = sz($R_OUT);
        my ($same2,$cs2,$rs2) = compare(@$args);
        my $stable = ($same2==$same && $cs2==$cs && $rs2==$rs) ? 'YES' : 'NO';
        $mismatch++;
        print "="x72, "\n";
        print "MISMATCH [$tag] reproduced_twice=$stable\n";
        print "  argv n=", scalar(@$args), " first=", pretty($args->[0]), "\n";
        print "  repro : ", (length(join('',@$args)) < 2000 ? repro(@$args) : "(argv too long to inline; tag=$tag)"), "\n";
        print "  cpp  ", status_str($cs), " stdout_bytes=$csz\n";
        print "  rust ", status_str($rs), " stdout_bytes=$rsz\n";
        system('cmp', $C_OUT, $R_OUT);
    }
    if (!$es) { $errdiff++; print "STDERR-DIFF [$tag]\n" if $errdiff <= 5 }
}
print "="x72, "\n";
print "cases executed : $executed\n";
print "cases skipped  : $skipped\n";
print "mismatches     : $mismatch\n";
print "stderr diffs   : $errdiff\n";

